{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "$id": "common/mappers_specific.schema.json",
    "title": "JSON Schema for mapper plugins.",
    "description": "https://docs.meltano.com/concepts/plugins#mappers",
    "type": "object",
    "additionalProperties": true,
    "properties": {
        "capabilities": {
            "type": "array",
            "items": {
                "type": "string",
                "enum": [
                    "about",
                    "schema-flattening",
                    "stream-maps",
                    "structured-logging"
                ]
            }
        },
        "mappings": {
            "description": "Name of the invokable mappings and their associated configs.",
            "type": "array",
            "items": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                    "name": {
                        "type": "string"
                    },
                    "config": {
                        "type": "object"
                    }
                }
            },
            "required": [
                "config",
                "name"
            ]
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "$id": "common/extractors_specific.schema.json",
    "title": "JSON Schema for extractor plugins.",
    "description": "https://docs.meltano.com/concepts/plugins#extractors",
    "type": "object",
    "additionalProperties": true,
    "properties": {
        "capabilities": {
            "type": "array",
            "items": {
                "type": "string",
                "enum": [
                    "properties",
                    "catalog",
                    "discover",
                    "state",
                    "about",
                    "stream-maps",
                    "schema-flattening",
                    "activate-version",
                    "batch",
                    "test",
                    "log-based",
                    "start-date",
                    "structured-logging"
                ]
            }
        },
        "metadata": {
            "type": "object",
            "description": "An object containing Singer stream and property metadata",
            "default": {}
        },
        "schema": {
            "type": "object",
            "description": "An object representing override rules for a Singer stream schema",
            "default": {}
        },
        "select": {
            "type": "array",
            "default": [
                "*.*"
            ],
            "description": "An array of entity selection rules in the form '<entity|*>.<attribute|*>'",
            "items": {
                "type": "string"
            }
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "$id": "common/files_specific.schema.json",
    "title": "JSON Schema for file bundle plugins.",
    "description": "https://docs.meltano.com/concepts/plugins#file-bundles",
    "type": "object",
    "additionalProperties": true,
    "properties": {
        "update": {
            "type": "object",
            "additionalProperties": {
                "type": "boolean"
            }
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "$id": "common/transforms_specific.schema.json",
    "title": "JSON Schema for transforms plugins.",
    "description": "https://docs.meltano.com/concepts/plugins#transforms",
    "type": "object",
    "additionalProperties": true,
    "properties": {
        "package_name": {
            "type": "string",
            "description": "The name of the dbt packages internal dbt project: the value of name in dbt_project.yml"
        },
        "vars": {
            "type": "object",
            "description": "An object containing dbt model variables that can be referenced from a model using the var function."
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "$id": "common/loaders_specific.schema.json",
    "title": "JSON Schema for loader plugins.",
    "description": "https://docs.meltano.com/concepts/plugins#loaders",
    "type": "object",
    "additionalProperties": true,
    "properties": {
        "capabilities": {
            "type": "array",
            "items": {
                "type": "string",
                "enum": [
                    "about",
                    "stream-maps",
                    "activate-version",
                    "batch",
                    "soft-delete",
                    "hard-delete",
                    "datatype-failsafe",
                    "schema-flattening",
                    "target-schema",
                    "validate-records",
                    "structured-logging"
                ]
            }
        },
        "dialect": {
            "description": "The name of the dialect of the target database, so that transformers in the same pipeline and Meltano UI's Analysis feature can determine the type of database to connect to."
        },
        "target_schema": {
            "description": "The name of the database schema the loader has been configured to load data into (assuming the destination supports schemas), so that transformers in the same pipeline can determine the database schema to load data from."
        }
    }
}
